#!/usr/bin/env node
/**
 * Quiet — token builder
 *
 * Source of truth: design-system/tokens/tokens.json
 * Outputs:
 *   design-system/tokens/quiet.tokens.css
 *   design-system/tokens/token-reference.md
 *
 * Usage:
 *   node scripts/build-tokens.mjs          # write
 *   node scripts/build-tokens.mjs --check  # fail if generated files are stale
 */

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const TOKENS_PATH = resolve(ROOT, "design-system/tokens/tokens.json");
export const CSS_PATH = resolve(ROOT, "design-system/tokens/quiet.tokens.css");
export const MD_PATH = resolve(ROOT, "design-system/tokens/token-reference.md");

export const COLOR_ALIASES = [
  ["canvas", "--canvas"],
  ["surface", "--surface"],
  ["surfaceRaised", "--surface-raised"],
  ["surfaceSunken", "--surface-sunken"],
  ["ink", "--ink"],
  ["inkSecondary", "--ink-2"],
  ["inkTertiary", "--ink-3"],
  ["inkInverse", "--ink-inverse"],
  ["line", "--line"],
  ["lineSoft", "--line-soft"],
  ["lineStrong", "--line-strong"],
  ["accent", "--accent"],
  ["accentHover", "--accent-hover"],
  ["accentInk", "--accent-ink"],
  ["accentWash", "--accent-wash"],
  ["accentLine", "--accent-line"],
  ["focus", "--focus"],
  ["selection", "--selection"],
  ["positive", "--positive"],
  ["positiveWash", "--positive-wash"],
  ["negative", "--negative"],
  ["negativeWash", "--negative-wash"],
  ["warning", "--warning"],
  ["warningWash", "--warning-wash"],
  ["primaryAction", "--primary"],
  ["primaryActionInk", "--primary-ink"],
  ["primaryActionHover", "--primary-hover"],
  ["hover", "--hover"],
  ["selected", "--selected"],
  ["scrim", "--scrim"],
  ["overlaySurface", "--overlay"],
  ["skeleton", "--skeleton"],
  ["disabledSurface", "--disabled-bg"],
  ["disabledInk", "--disabled-ink"],
];

export function loadTokens() {
  return JSON.parse(readFileSync(TOKENS_PATH, "utf8"));
}

function line(indent, name, value) {
  return `${indent}${name}: ${value};`;
}

export function renderCss(tokens) {
  const v = tokens.$meta.version;
  const c = tokens.color;
  const dv = tokens.dataViz;
  const elev = tokens.elevation;

  const declarations = (mode) => {
    const out = [];
    out.push(line("  ", "color-scheme", mode));
    for (const [key, cssVar] of COLOR_ALIASES) {
      const role = c[key];
      if (!role) throw new Error(`Missing colour role: ${key}`);
      out.push(line("  ", cssVar, role[mode]));
    }
    out.push("");
    out.push("  /* Data visualisation */");
    out.push(line("  ", "--chart-fill", dv.area[mode]));
    out.push(line("  ", "--chart-grid", dv.grid[mode]));
    out.push(line("  ", "--chart-muted", dv.neutral[mode]));
    for (const [key, series] of Object.entries(dv.series)) {
      out.push(line("  ", `--series-${key}`, series[mode]));
    }
    out.push("");
    out.push("  /* Elevation */");
    for (const [key, shadow] of Object.entries(elev[mode])) {
      out.push(line("  ", `--${key}`, shadow));
    }
    out.push("");
    out.push("  /* Optional app tints — monogram and active-app indicator only. Off by default. */");
    for (const [key, tint] of Object.entries(c.appTint)) {
      if (key.startsWith("$")) continue;
      out.push(line("  ", `--app-tint-${key}`, tint[mode]));
    }
    return out.join("\n");
  };

  return `/* ==========================================================================
   Quiet — generated token adapter
   Source: design-system/tokens/tokens.json
   Version: ${v}
   Do not edit this file. Run: npm run build:tokens
   ========================================================================== */

:root,
[data-mode="light"] {
${declarations("light")}
}

[data-mode="dark"] {
${declarations("dark")}
}
`;
}

function code(value) {
  return "`" + String(value).replaceAll("`", "\\`") + "`";
}

function table(headers, rows) {
  const head = `| ${headers.join(" | ")} |`;
  const sep = `| ${headers.map(() => "---").join(" | ")} |`;
  const body = rows.map((row) => `| ${row.join(" | ")} |`).join("\n");
  return `${head}\n${sep}\n${body}`;
}

export function renderMarkdown(tokens) {
  const v = tokens.$meta.version;
  const date = tokens.$meta.captured;
  const c = tokens.color;
  const t = tokens.typography;
  const dv = tokens.dataViz;

  const colorRows = Object.entries(c)
    .filter(([key, value]) => !key.startsWith("$") && key !== "appTint" && value && value.light)
    .map(([key, value]) => [
      code(key),
      code(value.light),
      code(value.dark),
      value.role,
    ]);

  const tintRows = Object.entries(c.appTint)
    .filter(([key]) => !key.startsWith("$"))
    .map(([key, value]) => [code(key), code(value.light), code(value.dark)]);

  const typeRows = Object.entries(t.scale).map(([key, value]) => [
    code(key),
    `${value.px}px`,
    `${value.rem}`,
    String(value.lineHeight),
    code(value.tracking),
    String(value.weight),
    value.use,
  ]);

  const spaceRows = Object.entries(tokens.space)
    .filter(([key]) => !key.startsWith("$"))
    .map(([key, value]) => [key, code(value)]);

  const radiusRows = Object.entries(tokens.radius)
    .filter(([key]) => !key.startsWith("$"))
    .map(([key, value]) => [code(key), code(value)]);

  const elevationRows = ["e0", "e1", "e2", "e3"].map((key) => [
    code(key),
    code(tokens.elevation.light[key]),
    code(tokens.elevation.dark[key]),
    tokens.elevation.usage[key],
  ]);

  const motionRows = [
    ...Object.entries(tokens.motion.duration).map(([key, value]) => [code(`duration.${key}`), code(value)]),
    ...Object.entries(tokens.motion.easing).map(([key, value]) => [code(`easing.${key}`), code(value)]),
  ];

  const dataRows = [
    ...Object.entries(dv.series).map(([key, value]) => [
      code(`series.${key}`),
      code(value.light),
      code(value.dark),
      value.role,
    ]),
    [code("grid"), code(dv.grid.light), code(dv.grid.dark), "Chart grid lines"],
    [code("axis"), code(dv.axis.light), code(dv.axis.dark), "Axis labels"],
    [code("area"), code(dv.area.light), code(dv.area.dark), "Area fill"],
  ];

  const contrastRows = tokens.contrast.pairs.map((pair) => [
    pair.pair,
    pair.light.toFixed(2),
    pair.dark.toFixed(2),
  ]);

  const densityRows = Object.entries(tokens.density)
    .filter(([, value]) => typeof value === "object")
    .flatMap(([mode, values]) =>
      Object.entries(values).map(([key, value]) => [mode, key, code(value)])
    );

  return `# Token reference

**Quiet ${v} · generated ${date}**

> Generated from [\`tokens.json\`](tokens.json) by \`scripts/build-tokens.mjs\`. Do not edit this file. Run \`npm run build:tokens\`.

The canonical source is [\`tokens.json\`](tokens.json). The CSS adapter is [\`quiet.tokens.css\`](quiet.tokens.css). Contrast is verified in [\`../docs/dark-mode.md\`](../docs/dark-mode.md) and by \`npm run check\`.

---

## Colour roles

${table(["Token", "Light", "Night", "Meaning"], colorRows)}

### Optional app tints (off by default)

Only the monogram tile and the 2px active-app indicator. Never buttons, links, focus, charts, status, selection or navigation icons.

${table(["Token", "Light", "Night"], tintRows)}

---

## Type

**Families**

| Role | Stack |
| --- | --- |
| UI | ${code(t.family.ui.stack)} |
| Display | ${code(t.family.display.stack)} |
| Numeric | ${code(t.family.numeric.stack)} |
| Mono | ${code(t.family.mono.stack)} |
| Cross-platform fallback | ${code(t.family.interFallback.stack)} |

${t.family.interFallback.adjustment}

**Scale**

${table(["Step", "px", "rem", "Line", "Tracking", "Weight", "Use"], typeRows)}

---

## Space and layout

**Space (4px base)**

${table(["Step", "Value"], spaceRows)}

**Layout**

| Item | Value |
| --- | --- |
| Rail width | ${code(tokens.layout.railWidth)} |
| Sidebar width | ${code(tokens.layout.navWidth)} |
| Inspector width | ${code(tokens.layout.inspectorWidth)} |
| Top bar height | ${code(tokens.layout.topbarHeight)} |
| Content max | ${code(tokens.layout.contentMax)} |
| Content padding | ${code(tokens.layout.contentPadX)} / ${code(tokens.layout.contentPadY)} |
| Card padding | ${code(tokens.layout.cardPadding)} |
| Gap | ${code(tokens.layout.gap)} |
| Prose measure | ${code(tokens.layout.proseMeasure)} |

**Density**

${table(["Mode", "Metric", "Value"], densityRows)}

---

## Shape and elevation

**Radius**

${table(["Token", "Value"], radiusRows)}

**Elevation**

${table(["Token", "Light", "Night", "Use"], elevationRows)}

---

## Motion

${table(["Token", "Value"], motionRows)}

Rules: ${tokens.motion.rules.join(" ")}

---

## Data visualisation

${table(["Token", "Light", "Night", "Meaning"], dataRows)}

${dv.rules.map((rule) => `- ${rule}`).join("\n")}

---

## Contrast

${tokens.contrast.$meta.standard}. Normal text ≥ ${tokens.contrast.$meta.normalText}:1; large text ≥ ${tokens.contrast.$meta.largeText}:1.

${table(["Pair", "Light", "Night"], contrastRows)}

${tokens.contrast.$meta.verified}
`;
}

export function generate({ check = false, quiet = false } = {}) {
  const tokens = loadTokens();
  const css = renderCss(tokens);
  const md = renderMarkdown(tokens);

  if (check) {
    const results = [];
    for (const [path, expected, label] of [
      [CSS_PATH, css, "quiet.tokens.css"],
      [MD_PATH, md, "token-reference.md"],
    ]) {
      let actual = "";
      try {
        actual = readFileSync(path, "utf8");
      } catch {
        results.push(`${label} is missing`);
        continue;
      }
      if (actual !== expected) results.push(`${label} is stale`);
    }
    return results;
  }

  writeFileSync(CSS_PATH, css, "utf8");
  writeFileSync(MD_PATH, md, "utf8");
  if (!quiet) {
    console.log(`Wrote ${CSS_PATH.replace(ROOT + "/", "")}`);
    console.log(`Wrote ${MD_PATH.replace(ROOT + "/", "")}`);
  }
  return [];
}

const isDirectRun = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isDirectRun) {
  const check = process.argv.includes("--check");
  const results = generate({ check });
  if (check) {
    if (results.length) {
      console.error("Generated token files are out of date:");
      for (const result of results) console.error(`  - ${result}`);
      console.error("Run: npm run build:tokens");
      process.exit(1);
    }
    console.log("Generated token files are current.");
  }
}
